module phaser_optimal(input clk,input rst_n,input start,input [3:0] room_count,input [7:0][31:0] room_x1,input [7:0][31:0] room_y1,input [7:0][31:0] room_x2,input [7:0][31:0] room_y2,input [31:0] beam_length,output reg [3:0] max_rooms,output reg done);parameter N=8;parameter MAX_CORNERS=4*N;parameter STATE_IDLE=3'd0,STATE_EXTRACT=3'd1,STATE_GENERATE=3'd2,STATE_INTERSECT=3'd3,STATE_UPDATE=3'd4,STATE_DONE=3'd5;reg [4:0] state_reg;reg [31:0] p1_idx,p2_idx;reg [31:0] max_rooms_reg;reg done_reg;reg [31:0] corner_x [MAX_CORNERS-1:0];reg [31:0] corner_y [MAX_CORNERS-1:0];reg [31:0] extract_counter;always @(posedge clk)begin if(!rst_n)begin state_reg<=STATE_IDLE;p1_idx<=0;p2_idx<=0;max_rooms_reg<=0;done_reg<=0;extract_counter<=0;end else begin case(state_reg)STATE_IDLE:begin if(start)state_reg<=STATE_EXTRACT;end STATE_EXTRACT:begin if(extract_counter<MAX_CORNERS)begin int room_num=extract_counter/4;int offset=extract_counter%4;if(room_num<room_count)begin case(offset)0:corner_x[extract_counter]=room_x1[room_num];corner_y[extract_counter]=room_y1[room_num];1:corner_x[extract_counter]=room_x1[room_num];corner_y[extract_counter]=room_y2[room_num];2:corner_x[extract_counter]=room_x2[room_num];corner_y[extract_counter]=room_y1[room_num];3:corner_x[extract_counter]=room_x2[room_num];corner_y[extract_counter]=room_y2[room_num];endcase end else begin corner_x[extract_counter]=0;corner_y[extract_counter]=0;end extract_counter<=extract_counter+1;end else begin state_reg<=STATE_GENERATE;extract_counter<=0;end endcase default:state_reg<=STATE_IDLE;endcase end assign max_rooms=max_rooms_reg;assign done=done_reg;endmodule